template:
% 参数由系统自动注入：\def\radius{3} \def\pdist{6} \def\fracone{0.55} \def\fractwo{0.85} \def\showtangent{1} \def\showsecond{0} \def\showradius{0} \def\showsimilar{0} \def\showangle{0} \def\showcenter{1} \def\labelp{P} \def\labelt{T} \def\labela{A} \def\labelb{B} \def\labelc{C} \def\labeld{D} \def\showcoord{0} \def\cx{0} \def\cy{0}
% P 在圆内（相交弦）与 P 在圆外（切割线/割线）共用同一套解析：过 P 的直线与圆的交点由 |P + t*u|^2 = radius^2 决定。
\pgfmathsetmacro{\outside}{\pdist < \radius ? 0 : 1}
% 视觉归一化：区分坐标模式与裸图模式
\ifnum\showcoord>0
  \pgfmathtruncatemacro{\xleft}{floor(min(\cx - \radius, \cx + \pdist) - 0.8)}
  \pgfmathtruncatemacro{\xright}{ceil(max(\cx + \radius, \cx + \pdist) + 0.8)}
  \pgfmathtruncatemacro{\ybottom}{floor(\cy - \radius - 0.8)}
  \pgfmathtruncatemacro{\ytop}{ceil(\cy + \radius + 0.8)}
  \pgfmathsetmacro{\xrange}{\xright - \xleft}
  \pgfmathsetmacro{\yrange}{\ytop - \ybottom}
  \pgfmathsetmacro{\figscale}{6.0 / max(\xrange, \yrange)}
\else
  \pgfmathsetmacro{\figscale}{\pdist < \radius ? 3/\radius : 6/(\radius + \pdist)}
\fi
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\pgfmathsetmacro{\loff}{0.34/\figscale}
% 比值 radius/OP：P 在圆内时无切线，钳位到 0.999 以免 acos/asin 定义域越界
\pgfmathsetmacro{\tratio}{min(\radius/\pdist, 0.999)}
% 从 P 看圆的半张角：P 在圆外时为 asin(radius/OP)，直线与 PO 夹角小于它才割到圆；P 在圆内时任意方向都是弦
\pgfmathsetmacro{\maxang}{\pdist < \radius ? 180 : asin(\tratio)}
% 切点 T 取上方（∠TOP = arccos(radius/OP)），两条割线一律向下偏，避免与切线重叠
\pgfmathsetmacro{\tha}{acos(\tratio)}
\pgfmathsetmacro{\Tx}{\radius*cos(\tha)}
\pgfmathsetmacro{\Ty}{\radius*sin(\tha)}
\pgfmathsetmacro{\tlen}{sqrt(max(\pdist*\pdist - \radius*\radius, 0.0001))}
\pgfmathsetmacro{\dirone}{180 + \fracone*\maxang}
\pgfmathsetmacro{\dirtwo}{180 + \fractwo*\maxang}
% 第一条线与圆的两个交点：P 在圆内时 t 两根一正一负，P 在圆外时两根同正（小根为近交点）
\pgfmathsetmacro{\uax}{cos(\dirone)}
\pgfmathsetmacro{\uay}{sin(\dirone)}
\pgfmathsetmacro{\pua}{\pdist*\uax}
\pgfmathsetmacro{\hlena}{sqrt(max(\pua*\pua - \pdist*\pdist + \radius*\radius, 0.0001))}
\pgfmathsetmacro{\tna}{-\pua - \hlena}
\pgfmathsetmacro{\tfa}{-\pua + \hlena}
\pgfmathsetmacro{\Ax}{\pdist + \tna*\uax}
\pgfmathsetmacro{\Ay}{\tna*\uay}
\pgfmathsetmacro{\Bx}{\pdist + \tfa*\uax}
\pgfmathsetmacro{\By}{\tfa*\uay}
% 线段区间取 min(t,0)..max(t,0)：P 在圆内自动得到整条弦 AB，P 在圆外自动得到割线 PAB，无需分支
\pgfmathsetmacro{\Aix}{\pdist + min(\tna,0)*\uax}
\pgfmathsetmacro{\Aiy}{min(\tna,0)*\uay}
\pgfmathsetmacro{\Aex}{\pdist + max(\tfa,0)*\uax}
\pgfmathsetmacro{\Aey}{max(\tfa,0)*\uay}
% 第二条线同理
\pgfmathsetmacro{\ubx}{cos(\dirtwo)}
\pgfmathsetmacro{\uby}{sin(\dirtwo)}
\pgfmathsetmacro{\pub}{\pdist*\ubx}
\pgfmathsetmacro{\hlenb}{sqrt(max(\pub*\pub - \pdist*\pdist + \radius*\radius, 0.0001))}
\pgfmathsetmacro{\tnb}{-\pub - \hlenb}
\pgfmathsetmacro{\tfb}{-\pub + \hlenb}
\pgfmathsetmacro{\Cx}{\pdist + \tnb*\ubx}
\pgfmathsetmacro{\Cy}{\tnb*\uby}
\pgfmathsetmacro{\Dx}{\pdist + \tfb*\ubx}
\pgfmathsetmacro{\Dy}{\tfb*\uby}
\pgfmathsetmacro{\Cix}{\pdist + min(\tnb,0)*\ubx}
\pgfmathsetmacro{\Ciy}{min(\tnb,0)*\uby}
\pgfmathsetmacro{\Cex}{\pdist + max(\tfb,0)*\ubx}
\pgfmathsetmacro{\Cey}{max(\tfb,0)*\uby}
% P 的字母：P 在圆外时放在 P 的外侧；P 在圆内时放进两条线夹出的较大空白角的角平分线上
\pgfmathsetmacro{\dtwoeff}{\showsecond > 0 ? \dirtwo : \dirone + 90}
\pgfmathsetmacro{\gapd}{\dtwoeff - \dirone}
\pgfmathsetmacro{\plang}{\pdist < \radius ? (\gapd > 90 ? \dirone + \gapd/2 : \dtwoeff + (180 - \gapd)/2) : 0}
\pgfmathsetmacro{\sangi}{\dirone + 180}
\pgfmathsetmacro{\eangi}{\dirtwo + 180}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % ===== 坐标系（showcoord=1 时绘制）=====
  \ifnum\showcoord>0
    \draw[->, thick] (\xleft-0.5, 0) -- (\xright+0.5, 0) node[right] {$x$};
    \draw[->, thick] (0, \ybottom-0.5) -- (0, \ytop+0.5) node[above] {$y$};
  \fi
  \draw[thick] (\cx,\cy) circle [radius=\radius];
  % 第一条线：P 在圆内是弦 AB，P 在圆外是割线 PAB
  \draw[thick] ({\cx+\Aix},{\cy+\Aiy}) -- ({\cx+\Aex},{\cy+\Aey});
  \ifnum\showsecond>0
    \draw[thick] ({\cx+\Cix},{\cy+\Ciy}) -- ({\cx+\Cex},{\cy+\Cey});
  \fi
  % 切线与切点半径只在 P 在圆外时存在
  \ifdim\outside pt>0pt
    \ifnum\showtangent>0
      \draw[thick] ({\cx+\pdist},{\cy}) -- ({\cx+\Tx + 0.2*\radius*cos(\tha+90)},{\cy+\Ty + 0.2*\radius*sin(\tha+90)});
      \fill ({\cx+\Tx},{\cy+\Ty}) circle [radius=\dotr pt];
      \node at ({\cx+\Tx + \loff*cos(\tha)},{\cy+\Ty + \loff*sin(\tha)}) {$\labelt$};
      % 切点半径 OT 与直角记号（切线⊥OT）
      \ifnum\showradius>0
        \draw[thick] (\cx,\cy) -- ({\cx+\Tx},{\cy+\Ty});
        \pgfmathsetmacro{\rmsz}{min(0.28/\figscale, \radius*0.22, \tlen*0.22)}
        \draw[thick] ({\cx+\Tx - \rmsz*cos(\tha)},{\cy+\Ty - \rmsz*sin(\tha)}) -- ({\cx+\Tx - \rmsz*cos(\tha) + \rmsz*cos(\tha-90)},{\cy+\Ty - \rmsz*sin(\tha) + \rmsz*sin(\tha-90)}) -- ({\cx+\Tx + \rmsz*cos(\tha-90)},{\cy+\Ty + \rmsz*sin(\tha-90)});
      \fi
    \fi
  \fi
  % 相似三角形辅助线
  \ifnum\showsimilar>0
    \ifdim\outside pt>0pt
      \ifnum\showtangent>0
        % △PTA ∽ △PBT（切割线定理）
        \draw[thick] ({\cx+\Tx},{\cy+\Ty}) -- ({\cx+\Ax},{\cy+\Ay});
        \draw[thick] ({\cx+\Tx},{\cy+\Ty}) -- ({\cx+\Bx},{\cy+\By});
      \fi
    \else
      \ifnum\showsecond>0
        % △APC ∽ △DPB（相交弦定理）
        \draw[thick] ({\cx+\Ax},{\cy+\Ay}) -- ({\cx+\Cx},{\cy+\Cy});
        \draw[thick] ({\cx+\Dx},{\cy+\Dy}) -- ({\cx+\Bx},{\cy+\By});
      \fi
    \fi
  \fi
  % P 处的角弧
  \ifnum\showangle>0
    \ifdim\outside pt>0pt
      \pgfmathsetmacro{\hasang}{max(\showtangent,\showsecond)}
      \ifdim\hasang pt>0pt
        % ∠P：切线与割线（无切线时为两条割线）的夹角，相似三角形中的公共角
        \pgfmathsetmacro{\sangp}{\showtangent > 0 ? 180 - \maxang : \dirone}
        \pgfmathsetmacro{\eangp}{\showtangent > 0 ? \dirone : \dirtwo}
        % 从圆外看的张角很小（两条割线之间可窄到 5 度），固定半径的弧会短到看不见，
        % 故按「弧长约 0.30cm」反推半径；上界取最近交点距离与 P 到圆的距离，保证弧不越过交点或圆。
        \pgfmathsetmacro{\angspan}{\eangp - \sangp}
        \pgfmathsetmacro{\arcneed}{(0.30/\figscale)*57.2958/max(\angspan,0.5)}
        \pgfmathsetmacro{\arcbnd}{\showtangent > 0 ? min(\tna,\tlen) : min(\tna,\tnb)}
        \pgfmathsetmacro{\arcrp}{min(max(0.4/\figscale, \arcneed), 0.75*\arcbnd, 0.8*(\pdist - \radius))}
        \draw[thick] ({\cx+\pdist + \arcrp*cos(\sangp)},{\cy+\arcrp*sin(\sangp)}) arc[start angle=\sangp, end angle=\eangp, radius=\arcrp];
      \fi
    \else
      \ifnum\showsecond>0
        % 对顶角 ∠APC 与 ∠BPD：射线 PA、PC 的方向为 dir+180，射线 PB、PD 的方向为 dir
        \pgfmathsetmacro{\arcri}{min(0.4/\figscale, abs(\tna)*0.3, abs(\tnb)*0.3, \tfa*0.3, \tfb*0.3)}
        \draw[thick] ({\cx+\pdist + \arcri*cos(\sangi)},{\cy+\arcri*sin(\sangi)}) arc[start angle=\sangi, end angle=\eangi, radius=\arcri];
        \draw[thick] ({\cx+\pdist + \arcri*cos(\dirone)},{\cy+\arcri*sin(\dirone)}) arc[start angle=\dirone, end angle=\dirtwo, radius=\arcri];
      \fi
    \fi
  \fi
  \ifnum\showcenter>0
    \fill (\cx,\cy) circle [radius=\dotr pt];
    \ifdim\outside pt>0pt
      \node[above left] at (\cx,\cy) {$O$};
    \else
      \node[below left] at (\cx,\cy) {$O$};
    \fi
  \fi
  % 交点字母以径向朝外为基准；径向与所在直线夹角过小会压线，此时把方向旋开到 30 度
  \foreach \lx/\ly/\lb/\ld in {\Ax/\Ay/\labela/\dirone, \Bx/\By/\labelb/\dirone}{
    \fill ({\cx+\lx},{\cy+\ly}) circle [radius=\dotr pt];
    \pgfmathsetmacro{\lrad}{atan2(\ly,\lx)}
    \pgfmathsetmacro{\ldif}{\lrad - \ld}
    \pgfmathsetmacro{\lnorm}{\ldif - 360*round(\ldif/360)}
    \pgfmathsetmacro{\labss}{abs(\lnorm)}
    \pgfmathsetmacro{\lclr}{min(\labss, 180 - \labss)}
    \pgfmathsetmacro{\lsgn}{\lnorm < 0 ? -1 : 1}
    \pgfmathsetmacro{\lang}{\lclr < 30 ? (\labss < 90 ? \ld + \lsgn*30 : \ld + 180 - \lsgn*30) : \lrad}
    \node at ({\cx+\lx + \loff*cos(\lang)},{\cy+\ly + \loff*sin(\lang)}) {$\lb$};
  }
  \ifnum\showsecond>0
    \foreach \lx/\ly/\lb/\ld in {\Cx/\Cy/\labelc/\dirtwo, \Dx/\Dy/\labeld/\dirtwo}{
      \fill ({\cx+\lx},{\cy+\ly}) circle [radius=\dotr pt];
      \pgfmathsetmacro{\lrad}{atan2(\ly,\lx)}
      \pgfmathsetmacro{\ldif}{\lrad - \ld}
      \pgfmathsetmacro{\lnorm}{\ldif - 360*round(\ldif/360)}
      \pgfmathsetmacro{\labss}{abs(\lnorm)}
      \pgfmathsetmacro{\lclr}{min(\labss, 180 - \labss)}
      \pgfmathsetmacro{\lsgn}{\lnorm < 0 ? -1 : 1}
      \pgfmathsetmacro{\lang}{\lclr < 30 ? (\labss < 90 ? \ld + \lsgn*30 : \ld + 180 - \lsgn*30) : \lrad}
      \node at ({\cx+\lx + \loff*cos(\lang)},{\cy+\ly + \loff*sin(\lang)}) {$\lb$};
    }
  \fi
  \fill ({\cx+\pdist},\cy) circle [radius=\dotr pt];
  \node at ({\cx+\pdist + \loff*cos(\plang)},{\cy+\loff*sin(\plang)}) {$\labelp$};
\end{tikzpicture}
